/** Technology `name` (exactly as stored) -> logos slug; only names with real colour art are present. */
export const POPULAR_LOGO_SLUG_BY_NAME: Record<string, string> = {
  'OpenAI': 'openai-icon',
  'Claude': 'claude-icon',
  'Gemini': 'google-gemini-icon',
  'Hugging Face': 'hugging-face-icon',
  'AWS': 'aws',
  'Microsoft Azure': 'microsoft-azure',
  'Google Cloud': 'google-cloud',
  'Python': 'python',
  'Jupyter': 'jupyter',
  'Pandas': 'pandas-icon',
  'NumPy': 'numpy',
  'Raspberry Pi': 'raspberry-pi',
  'Arduino': 'arduino',
  'IBM Quantum': 'ibm',
  'Ethereum': 'ethereum',
  'Solidity': 'solidity',
  'Google Analytics': 'google-analytics',
  'Google Ads': 'google-ads',
  'Meta Ads / Meta Business Suite': 'meta-icon',
  'Linux': 'linux-tux',
};

export interface PopularLogoPick {
  name: string;
  slug: string;
}

/**
 * Up to `max` (default 2) technologies from this course that have real
 * colour art, in the order the course already lists them (core techs
 * first) -- so "popular" falls naturally out of how each course's own
 * technologies array is already ordered, rather than a second hand-kept
 * per-course list.
 */
export function popularLogosForCourse(
  technologies: { name: string }[],
  max = 2,
): PopularLogoPick[] {
  const picks: PopularLogoPick[] = [];
  for (const t of technologies) {
    const slug = POPULAR_LOGO_SLUG_BY_NAME[t.name];
    if (slug) picks.push({ name: t.name, slug });
    if (picks.length >= max) break;
  }
  return picks;
}

export function PopularLogoBadges({ technologies }: { technologies: { name: string }[] }) {
  const picks = popularLogosForCourse(technologies);
  if (picks.length === 0) return null;

  return (
    <div className="course-card__logos" aria-hidden="true">
      {picks.map((pick, i) => (
        <span
          key={pick.slug}
          className="course-card__logo-badge"
          style={{ '--logo-delay': `${i * 0.6}s` } as CSSProperties}
          title={pick.name}
        >
          <PopularLogo slug={pick.slug} />
        </span>
      ))}
    </div>
  );
}

function PopularLogo({ slug }: { slug: string }) {
  const art = POPULAR_LOGOS[slug];
  if (!art) return null;
  return (
    <svg
      width="18"
      height="18"
      viewBox={art.viewBox}
      preserveAspectRatio="xMidYMid meet"
      // Trusted, vendored SVG markup (see the file-level doc comment) -- never user input.
      dangerouslySetInnerHTML={{ __html: art.body }}
    />
  );
}
